using Microsoft.EntityFrameworkCore;
public sealed record Order(Guid Id, decimal Net);
public sealed class Invoice(Guid orderId, decimal total)
{
    public Guid OrderId { get; } = orderId;
    public decimal Total { get; } = total;
    public string Number { get; } = $"INV-{orderId:N}";
    public static Invoice For(Guid orderId, decimal net) => new(orderId, net * 1.14m);
}
public sealed class ShopDb(DbContextOptions<ShopDb> options) : DbContext(options)
{
    public DbSet<Order> Orders => Set<Order>();
    public DbSet<Invoice> Invoices => Set<Invoice>();
}
public sealed class BillingDb(DbContextOptions<BillingDb> options) : DbContext(options)
{
    public DbSet<Invoice> Invoices => Set<Invoice>();
}
